  function burst(x,y,color,count=10){state.particles.push({x,y,vx:0,vy:0,life:.24,max:.24,color,r:21,sprite:true});state.particles.push({x,y,vx:0,vy:0,life:.42,max:.42,color,r:8,kind:'ring'});state.particles.push({x,y,vx:0,vy:0,life:.13,max:.13,color:'#ffffff',r:7,kind:'core'});for(let i=0;i<count;i++){const a=Math.random()*TAU,v=35+Math.random()*165;state.particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.35+Math.random()*.5,max:.8,color,r:1+Math.random()*2.5});}}
  function flash(){let f=document.querySelector('.screen-flash');if(!f){f=document.createElement('div');f.className='screen-flash';$('game').append(f);}f.classList.remove('hit');void f.offsetWidth;f.classList.add('hit');}
  function damage(enemy=null,requiresShield=false){if(consumeShield()){const p=enemy?point(enemy.angle,enemy.r):point(state.angle,orbitR*.54);burst(p.x,p.y,'#67dff4',12);feed('SHIELD CHARGE ABSORBED THE BREACH');toast(`🛡 -1 · ${state.shieldCharges}/3`);return;}const aligned=enemy&&Math.abs(delta(state.angle,enemy.angle))<=(state.upgrades.has('wide')?24:13);if(requiresShield){if(aligned&&!state.shieldActive)state.stats.timingMisses++;else if(!aligned)state.stats.bearingErrors++;}const shipPoint=point(state.angle,orbitR*.54);burst(shipPoint.x,shipPoint.y,'#ff7180',18);state.playerHp=Math.max(0,state.playerHp-1);state.streak=0;state.shake=.28;sfx('damage');flash();if(requiresShield&&!aligned)feed(`SHIELD POSITION ERROR · signal θ ${angleText(enemy.angle)} at (${fmt(xy(enemy.angle).x)}, ${fmt(xy(enemy.angle).y)})`);else if(requiresShield)feed('TIMING ERROR · bearing aligned; activate the shield sooner');else feed('HOSTILE BREACH · PILOT HIT');toast(`♥ -1 · ${state.playerHp}/${state.maxPlayerHp}`,true);updateHUD();if(state.playerHp<=0){state.stats.retries++;finishRun(false);}}
  function clearEnemy(e,training=false){const p=point(e.screenAngle??e.angle,e.r);burst(p.x,p.y,e.kind==='shield-drone'?'#a888ff':'#ffd27b',14);state.enemies=state.enemies.filter(x=>x!==e);if(state.selectedTargetId===e.id)state.selectedTargetId=null;state.stats.hits++;sfx('explode');if(training){state.trainingValue=e.valueKey;feed(`MATCH CONFIRMED · ${e.coordinate||'y'} = ${e.valueKey}`);sfx('hit');setTimeout(()=>{if(state.mode==='tutorial')completeTrainingStep();},document.documentElement.classList.contains('reduce-motion')?250:900);return;}if(state.shieldCharges<3&&Math.random()<.22){state.shieldDrops.push({angle:e.screenAngle??e.angle,r:e.r,life:9});}state.energy=Math.min(100,state.energy+10);const solvedKey=signalMistakeKey(e);state.questionMistakes.delete(solvedKey);if(state.autoHintKey===solvedKey){state.autoHint='';state.autoHintKey='';state.autoHintUntil=0;$('auto-hint').hidden=true;}state.waveKills++;state.progress++;if(state.endlessMode)state.endlessWave=Math.floor(state.waveKills/10);state.streak++;state.score+=100+Math.min(5,state.streak-1)*25;sfx('hit');const q=xy(e.angle);feed(`DIRECT HIT · θ ${angleText(e.angle)} · ${e.coordinate||'y'} = ${e.valueKey} · (${fmt(q.x)}, ${fmt(q.y)})`);if(e.kind==='shield-drone')toast('COORDINATE HACK CONFIRMED');if(!state.endlessMode&&state.waveKills>=WAVE_QUOTAS[state.wave]&&state.enemies.length===0)waveChanged();updateHUD();}
  function damageEnemy(e,training=false,amount=1){e.hp-=amount;const p=point(e.angle,e.r);burst(p.x,p.y,e.hp>0?'#ffd27b':'#f4a4ff',e.hp>0?5:12);if(e.hp<=0)clearEnemy(e,training);else{feed(`ARMOR HIT · ${e.valueKey} · ${e.hp} HP LEFT`);toast(`♥ ${e.hp}/${e.maxHp} · HIT AGAIN`);sfx('hit');}}
  function waveChanged(){if(state.wave<2){state.wave++;state.waveKills=0;state.waveSpawned=0;state.waveCue=state.wave;state.hintLevel=0;state.enemyShots=[];state.spawn=enemySpawnDelay(state.wave);toast(`WAVE ${state.wave+1} / 3 · ${currStage().objectives[state.wave]}`);sfx('clear');}else stageClear();updateHUD();}
    function blockEnemy(e){const p=point(e.angle,e.r);burst(p.x,p.y,'#67cde8',9);e.r=Math.min(W,H)*.08+36;e.speed=0;e.passed=true;state.streak=0;sfx('shield');const q=xy(e.angle);feed(`SHIELD BLOCK · ${fmt(q.x)}, ${fmt(q.y)} · SELECT ${e.valueKey} TO FINISH`);toast('🛡 BLOCK · FINISH WITH MATCHING WEAPON');}function hitBoss(bullet){const p=bossPoint(),q=xy(state.bossAngle);burst(p.x,p.y,'#ff7180',17);state.bossHits++;state.energy=Math.min(100,state.energy+12);sfx('explode');state.progress=state.bossHits;state.score+=260+state.bossPhase*90;state.stats.hits++;state.streak++;sfx('hit');feed(`ARMOR BREACH · θ ${angleText(state.bossAngle)} → (${fmt(q.x)}, ${fmt(q.y)})`);if(state.bossHits>=15){bossVictory();return;}const phase=Math.floor(state.bossHits/5),phaseChanged=phase!==state.bossPhase;if(phaseChanged){state.bossPhase=phase;state.enemies=[];sfx('boss');playBossPhaseDialogue(phase,'playing');toast(`ARMOR PHASE ${phase+1} · TARGET SIGNAL SHIFT`,true);}assignBossWeakpoint();updateHUD();}
  function waveClear(){state.mode='terminal';state.score+=250;sfx('clear');const w=currentWave();showTerminal('WAVE COMPLETE',`WAVE ${w+1} SECURED`,`เป้าหมาย ${w+1} / 3 สำเร็จ · Weapon Match ${weaponMatchAccuracy()}%`,'ดำเนินภารกิจต่อ',()=>{state.mode='playing';overlay.classList.add('hidden');updateHUD();});}
  function createLearningMetrics(){const quadrants={};for(const name of ['I','II','III','IV'])quadrants[name]={attempts:0,correct:0};return{angle:{attempts:0,correct:0},cosine:{attempts:0,correct:0},sine:{attempts:0,correct:0},quadrants};}
  function trackLearningResult(target,correct){const metrics=state.stats.learning||(state.stats.learning=createLearningMetrics()),topic=target.solutionType==='angle'?'angle':target.coordinate==='x'?'cosine':'sine',bucket=metrics[topic];bucket.attempts++;if(correct)bucket.correct++;const q=quadrant(target.angle);if(q!=='AXIS'&&metrics.quadrants[q]){metrics.quadrants[q].attempts++;if(correct)metrics.quadrants[q].correct++;}}
  function weaponMatchAccuracy(){return state.stats.bearingAttempts?Math.round(state.stats.bearingCorrect/state.stats.bearingAttempts*100):0;}
  function stageClear(){if(state.mode!=='playing')return;state.score+=300;sfx('clear');if(state.practice){state.mode='terminal';showTerminal('PRACTICE COMPLETE','ฝึกภารกิจสำเร็จ',`Weapon Match ${weaponMatchAccuracy()}% · Combat Score ${state.score}`,'กลับหน้าเมนู',()=>location.href='index.html');return;}if(state.endlessMode){state.clearedMissions++;const nextStage=(state.stage+1)%3;toast(`ENDLESS · MISSION ${state.clearedMissions+1}`);startStage(nextStage,false);return;}state.clearedMissions++;try{const unlocked=Number(localStorage.getItem('orbit-defender-route-unlocked'))||0;localStorage.setItem('orbit-defender-route-unlocked',String(Math.max(unlocked,Math.min(3,state.stage+1))));}catch(_){}if(state.stage===0)state.shieldUnlocked=true;if(state.stage===1)state.scannerUnlocked=true;state.mode='after-action-transition';const pause=document.documentElement.classList.contains('reduce-motion')?120:850;setTimeout(()=>startStoryDialog(LEVEL_POST_STORIES[state.stage],`LEVEL ${String(state.stage+1).padStart(2,'0')} · AFTER ACTION`,()=>startZombieIntermission(state.stage+1)),pause);}
  function showTerminal(kicker,title,copy,button,action,presentation=null){overlay.classList.remove('boss-brief-screen');if(kicker!=='FLIGHT SYSTEM PAUSED')setSceneMusic(kicker==='CAMPAIGN COMPLETE'||kicker==='PRACTICE FLIGHT'&&title.includes('สำเร็จ')?'victory':'fail');state.mode='terminal';box.classList.remove('is-academy');overlay.classList.remove('academy-screen','is-lesson-dialogue');$('academy-story').hidden=true;$('academy-astra').hidden=true;$('lesson-stage').hidden=true;box.classList.remove('has-results','is-pause');$('overlay-title').innerHTML=`${presentation?.planetName||title}<span>${kicker}</span>`;$('overlay-copy').hidden=false;$('overlay-copy').textContent=copy;const resultVisual=$('result-visual'),briefControls=box.querySelector('.brief-controls');resultVisual.hidden=!presentation;briefControls.hidden=Boolean(presentation);const isPause=kicker==='FLIGHT SYSTEM PAUSED';if(isPause){box.classList.add('is-pause');box.querySelector('.flight-flow').hidden=true;briefControls.innerHTML='';briefControls.hidden=true;}else{box.querySelector('.flight-flow').hidden=false;}box.classList.toggle('has-results',Boolean(presentation));$('mission-art').hidden=true;$('lesson-art').hidden=true;$('tutorial-tools').hidden=true;$('training-continue').hidden=true;if(presentation){const planet=$('result-visual').querySelector('.result-hero img');planet.src=`assets/${presentation.planetImage}`;planet.alt=presentation.planetName;$('result-status').textContent=presentation.status;$('result-loot').textContent=presentation.loot;$('result-score').textContent=String(presentation.score);$('result-missions').textContent=`${presentation.missions} / 4`;$('result-accuracy').textContent=`${presentation.accuracy}%`;$('result-minigames').textContent=`${presentation.minigamesPassed} / ${presentation.minigamesTotal}`;$('result-strength').textContent=presentation.strength;$('result-improve').textContent=presentation.improve;$('learning-topic-grid').innerHTML=learningAssessmentMarkup(presentation);}$('upgrade-choices').hidden=true;$('run-actions').hidden=true;$('launch').hidden=false;$('launch').querySelector('span').textContent=button;$('launch').onclick=()=>action?.();$('retry-wave').hidden=true;$('cancel-mission').hidden=!isPause;overlay.classList.remove('hidden');updateHUD();}
  function assessmentStatus(attempts,accuracy,minSamples=3){if(attempts<minSamples)return attempts?'ข้อมูลยังน้อย':'ยังไม่มีข้อมูล';if(accuracy>=80)return'ทำได้ดี';if(accuracy>=60)return'กำลังพัฒนา';return'ควรฝึกเพิ่ม';}
  function assessmentTopic(title,attempts,correct,advice,good,extra='',minSamples=3,evidenceLabel='ข้อถูก'){const accuracy=attempts?Math.round(correct/attempts*100):0,status=assessmentStatus(attempts,accuracy,minSamples),kind=attempts<minSamples?'low':accuracy>=80?'good':accuracy>=60?'developing':'improve',note=attempts<minSamples?'ฝึกหัวข้อนี้เพิ่มเพื่อให้ประเมินได้ชัดขึ้น':accuracy>=80?good:advice;return`<article class="learning-topic ${kind}"><header><b>${title}</b><span>${status}</span></header><div class="learning-topic-result"><strong>${attempts?`${accuracy}%`:'—'}</strong><small>${correct} / ${attempts} ${evidenceLabel}</small></div><div class="learning-topic-meter"><i style="width:${accuracy}%"></i></div><p>${note}</p>${extra}</article>`;}
  function learningAssessmentMarkup(presentation){const learning=presentation.learning||createLearningMetrics(),minigames=presentation.minigames||[],passed=minigames.filter(m=>m.success).length,quadrants=['I','II','III','IV'].map(q=>{const item=learning.quadrants?.[q]||{attempts:0,correct:0},rate=item.attempts?`${Math.round(item.correct/item.attempts*100)}%`:'—';return`<span>Q${q} <b>${rate}</b><small>${item.correct}/${item.attempts}</small></span>`;}).join(''),quadrantAttempts=['I','II','III','IV'].reduce((sum,q)=>sum+(learning.quadrants?.[q]?.attempts||0),0),quadrantCorrect=['I','II','III','IV'].reduce((sum,q)=>sum+(learning.quadrants?.[q]?.correct||0),0),weaponAttempts=Number(presentation.shots)||0,weaponCorrect=Number.isFinite(presentation.weaponCorrect)?presentation.weaponCorrect:Math.round((presentation.accuracy||0)*weaponAttempts/100),miniExtra=minigames.length?`<p class="learning-topic-note">คะแนนมินิเกมเฉลี่ย ${Math.round(minigames.reduce((sum,m)=>sum+(Number(m.score)||0),0)/minigames.length)} · ผ่าน ${passed} จาก ${minigames.length}</p>`:'';return[
    assessmentTopic('ระบุมุม θ จากพิกัด (x, y)',learning.angle?.attempts||0,learning.angle?.correct||0,'ทบทวนการจับคู่พิกัดทั้งสองค่าเพื่อหามุมที่ถูกต้อง','ถอดรหัสพิกัดกลับเป็นมุมได้แม่นยำ'),
    assessmentTopic('โคไซน์: x = cos θ',learning.cosine?.attempts||0,learning.cosine?.correct||0,'ฝึกอ่านค่า x และเครื่องหมายตามตำแหน่งบนวงกลมหนึ่งหน่วย','อ่านค่าโคไซน์และเครื่องหมายของ x ได้แม่นยำ'),
    assessmentTopic('ไซน์: y = sin θ',learning.sine?.attempts||0,learning.sine?.correct||0,'ฝึกอ่านค่า y และเครื่องหมายด้านบน/ล่างของวงกลม','อ่านค่าไซน์และเครื่องหมายของ y ได้แม่นยำ'),
    assessmentTopic('Quadrant และเครื่องหมาย',quadrantAttempts,quadrantCorrect,'ทบทวนเครื่องหมาย x/y ในแต่ละ Quadrant ก่อนเลือกคำตอบ','แยกเครื่องหมายตาม Quadrant ได้แม่นยำ',`<div class="quadrant-breakdown">${quadrants}</div>`),
    assessmentTopic('เลือกอาวุธให้ตรงกับโจทย์',weaponAttempts,weaponCorrect,'อ่านก่อนว่าโจทย์ถามมุมหรือค่า x/y แล้วเลือกปืนชนิดนั้น','จับคู่โจทย์กับอาวุธได้แม่นยำ','',3,'นัดตรง'),
    assessmentTopic('ประยุกต์ใช้ในมินิเกม',minigames.length,passed,'ลองเล่นมินิเกมที่ยังไม่ผ่านอีกครั้ง และนำค่ามุม/พิกัดไปใช้','นำความรู้ไปใช้ผ่านมินิเกมได้ดี',miniExtra,1,'เกมผ่าน')
  ].join('');}
  function resultPresentation(record,status,loot,strength,improve){const minigames=record.minigames||[];return{status,loot,score:record.combatScore,missions:record.missionsCleared,accuracy:record.weaponMatchAccuracy,weaponCorrect:record.weaponCorrect,shots:record.shots,learning:record.learning,minigames,minigamesPassed:minigames.filter(m=>m.success).length,minigamesTotal:minigames.length,planetName:STAGE_DESTINATION_NAMES[state.stage]||STAGE_DESTINATION_NAMES[0],planetImage:state.stage===3?'nox-command-base-menu.png':(STAGE_PLANET_ART[state.stage]||STAGE_PLANET_ART[0]),strength,improve};}
  function offerUpgrade(){const pool=UPGRADES.filter(u=>(u.id==='repair'||u.id==='weapon_drop'||!state.upgrades.has(u.id))&&(u.id!=='weapon_drop'||state.weapons.length<SIN_VALUES.length));state.pendingDraft=[];while(state.pendingDraft.length<3&&pool.length){const i=Math.floor(Math.random()*pool.length);state.pendingDraft.push(pool.splice(i,1)[0]);}$('upgrade-choices').innerHTML=state.pendingDraft.map(u=>`<button class="upgrade-choice" data-upgrade="${u.id}"><b>${u.title}</b>${u.text}</button>`).join('');$('upgrade-choices').hidden=false;$('run-actions').hidden=true;$('mission-completion').hidden=false;$('game').classList.add('mission-complete');$('completion-copy').textContent='เลือกอัปเกรดหนึ่งชิ้นก่อนออกเดินทาง';overlay.classList.add('hidden');state.mode='reward';updateHUD();}
  function applyUpgrade(id){const u=UPGRADES.find(x=>x.id===id);if(!u)return;state.upgrades.add(id);if(id==='weapon_drop'){const missing=SIN_VALUES.filter(v=>!state.weapons.some(w=>w.key===v.key));const v=missing[(Math.random()*missing.length)|0];if(v){const colors=['#67e6ff','#ffd27b','#df8aff','#7af0ba','#ff8b99','#94a5ff'];state.weapons.push({key:v.key,value:v.value,name:'RELIC',color:colors[state.weapons.length%colors.length]});state.activeWeapon=state.weapons.length-1;state.relics.push(`WEAPON ${v.key}`);}}else state.relics.push(u.title);if(id==='repair'&&state.playerHp<state.maxPlayerHp){state.playerHp++;toast('♥ +1');}if(id==='overdrive')state.overdrive=true;$('upgrade-choices').hidden=true;$('run-actions').hidden=false;$('continue-run').textContent='RANDOM MINIGAME · 30s ↗';$('completion-copy').textContent=`รับอัปเกรด ${u.title} แล้ว · RELICS ${state.relics.length}`;updateHUD();sfx('clear');}
  $('upgrade-choices').addEventListener('click',e=>{const b=e.target.closest('[data-upgrade]');if(b)applyUpgrade(b.dataset.upgrade);});
  $('continue-run').addEventListener('click',()=>{ $('run-actions').hidden=true;$('mission-completion').hidden=true;$('game').classList.remove('mission-complete');startZombieIntermission(state.stage+1); });
  $('extract-run').addEventListener('click',()=>{$('mission-completion').hidden=true;$('game').classList.remove('mission-complete');finishRun(true);});
  function recordMinigame(success,reason='complete',score=0){const result={level:state.stage+1,content:['basic','reflection','quadrants','boss'][state.stage]||'basic',success,reason,score,when:new Date().toISOString()};try{const results=JSON.parse(localStorage.getItem('orbit-defender-minigames')||'[]');results.push(result);localStorage.setItem('orbit-defender-minigames',JSON.stringify(results));localStorage.setItem('orbit-defender-minigame-current',JSON.stringify({...result,status:'complete'}));}catch(_){}return result;}
  function recordRun(outcome='completed'){const data={when:new Date().toISOString(),outcome,learningUnit:state.unit,combatScore:state.score,missionsCleared:state.clearedMissions,relics:[...state.relics],weaponMatchAccuracy:weaponMatchAccuracy(),weaponCorrect:state.stats.bearingCorrect,shots:state.stats.shots,hits:state.stats.hits,weaponMismatches:state.stats.bearingErrors,learning:JSON.parse(JSON.stringify(state.stats.learning||createLearningMetrics())),hints:state.stats.hints,retries:state.stats.retries,minigames:(()=>{try{return JSON.parse(localStorage.getItem('orbit-defender-minigames')||'[]')}catch(_){return[]}})(),elapsedSeconds:Math.round((Date.now()-state.stats.started)/1000)};try{const runs=JSON.parse(localStorage.getItem('orbit-defender-runs')||'[]');runs.push(data);localStorage.setItem('orbit-defender-runs',JSON.stringify(runs.slice(-20)));localStorage.setItem('orbit-defender-last-run',JSON.stringify(data));}catch(_){}return data;}
  function finishRun(extracted,victory=false){if(state.runEnded)return;if(state.practice){state.runEnded=true;state.mode=victory?'victory':'gameover';showTerminal('PRACTICE FLIGHT',victory?'ฝึกปราบ NOX สำเร็จ':'จบการทดลองเล่น','ผลการฝึกจะไม่เปลี่ยนแปลงแคมเปญ','กลับหน้าเมนู',()=>location.href='index.html');return;}state.runEnded=true;state.mode=victory?'victory':'gameover';if(state.endlessMode){if(!victory)clearCampaignCheckpoint();let best=0;try{best=Number(localStorage.getItem('orbit-defender-endless-best'))||0;if(state.score>best){best=state.score;localStorage.setItem('orbit-defender-endless-best',String(best));}}catch(_){}showTerminal('ENDLESS SURVIVAL',state.score>=best?'สถิติใหม่!':'สิ้นสุดการเอาตัวรอด',`คะแนนรอบนี้ ${state.score.toLocaleString()} · สถิติส่วนตัว ${best.toLocaleString()}`,'กลับสู่หน้าเมนู',restart);return;}clearCampaignCheckpoint();const outcome=victory?'victory':extracted?'extracted':'defeat',record=recordRun(outcome),title=victory?'NOX flagship disabled':extracted?'ถอนตัวสำเร็จ':'NOX COMMAND BASE ถูกปิดระบบ',kicker=victory?'CAMPAIGN COMPLETE':extracted?'RUN EXTRACTED · LOOT SECURED':'RUN OVER',relicText=record.relics.length?record.relics.join(', '):'ไม่มี',loot=extracted||victory?`กู้คืน: ${relicText}`:`สูญเสีย: ${relicText}`,strength=record.weaponMatchAccuracy>=70?'เลือกอาวุธตรงสัญญาณได้ดี':`ฝึกจับคู่มุมกับอาวุธเพิ่ม (ความแม่น ${record.weaponMatchAccuracy}%)`,improve=record.weaponMismatches>0?`ลดการยิงผิดสัญญาณ ${record.weaponMismatches} ครั้ง`:'รักษาความแม่นยำและลดเวลาตัดสินใจ';showTerminal(kicker,title,'ผลการบินและข้อเสนอแนะอยู่ด้านล่าง','กลับสู่หน้าเมนู',restart,resultPresentation(record,kicker,loot,strength,improve));}
  function bossVictory(){if(state.mode!=='playing')return;state.score+=500;state.clearedMissions++;if(!state.practice)try{localStorage.setItem('orbit-defender-endless-unlocked','true');}catch(_){}state.mode='ending';startStoryDialog(CAMPAIGN_ENDING_STORY,'CAMPAIGN COMPLETE · DEGREE CORES RESTORED',()=>finishRun(false,true));}
  function showAssessment(){state.mode='victory';const record=recordRun(),strength=record.weaponMatchAccuracy>=70?'เลือกอาวุธตรงสัญญาณได้ดี':`ฝึกจับคู่มุมกับอาวุธเพิ่ม (ความแม่น ${record.weaponMatchAccuracy}%)`,improve=record.weaponMismatches>0?`ลดการยิงผิดสัญญาณ ${record.weaponMismatches} ครั้ง`:'รักษาความแม่นยำและลดเวลาตัดสินใจ';showTerminal('POST-FLIGHT ASSESSMENT','สรุปผลการบิน','ผลการฝึกและข้อเสนอแนะอยู่ด้านล่าง','กลับสู่หน้าเมนู',restart,resultPresentation(record,'POST-FLIGHT ASSESSMENT','ผลการฝึก',strength,improve));}
  function restart(redirect=true,clearResults=true){if(!redirect&&clearResults){try{['orbit-defender-runs','orbit-defender-last-run','orbit-defender-minigames','orbit-defender-minigame-current',CAMPAIGN_MINIGAMES_KEY].forEach(k=>localStorage.removeItem(k));}catch(_){}clearCampaignCheckpoint();}state.score=0;state.maxPlayerHp=DIFFICULTIES[state.difficulty].playerHp;state.playerHp=state.maxPlayerHp;state.energy=100;state.energyRest=0;state.fireCooldown=0;state.shieldCharges=0;state.shieldDrops=[];state.questionMistakes=new Map();state.autoHint='';state.autoHintKey='';state.progress=0;state.streak=0;state.stage=0;state.wave=0;state.practice=false;state.upgrades.clear();state.weapons=START_WEAPONS.map(w=>({...w}));state.unlockedQuadrants=1;state.activeWeapon=0;state.activeWeaponType='value';state.activeAngleWeapon=0;state.aimAngle=0;state.angle=0;state.keys.cooldown=0;state.relics=[];state.clearedMissions=0;state.runEnded=false;state.shieldUnlocked=false;state.scannerUnlocked=false;state.overdrive=false;state.stats={shots:0,hits:0,bearingAttempts:0,bearingCorrect:0,bearingErrors:0,timingMisses:0,retries:0,scannerUses:0,hints:0,stageShots:0,stageLocks:0,started:Date.now(),learning:createLearningMetrics()};state.tutorialStep=0;if(redirect)location.href='index.html';}

  function activateScanner(){if(!state.scannerUnlocked&&state.stage<2&&state.mode==='playing'){toast('SCANNER UNLOCKS AFTER QUADRANT SHIELD');return;}if(state.mode!=='playing'&&state.mode!=='tutorial')return;if(state.scannerCooldown>0){toast(`SCANNER RECHARGING · ${Math.ceil(state.scannerCooldown)}s`);return;}const target=state.mode==='tutorial'?state.trainingTarget:state.stage===3?state.bossAngle:nearestEnemy()?.angle;if(target===undefined){toast('NO COORDINATE SIGNAL');return;}state.scanner=3.5;state.scannerCooldown=7;state.stats.scannerUses++;if(state.stage===2)for(const e of state.enemies)if(e.kind==='shield-drone')e.open=true;sfx('scan');feed(`COORDINATE SCAN · SIGNAL BEARING ${angleText(target)}`);toast(`SCANNER LOCK · ${angleText(target)}`);updateTelemetry();}
  function hint(){if(state.mode!=='playing'&&state.mode!=='tutorial')return;state.hintLevel=Math.min(3,state.hintLevel+1);state.hints++;state.stats.hints++;const e=nearestEnemy(),target=state.mode==='tutorial'?state.trainingTarget:state.stage===3?state.bossAngle:e?.angle;if(target===undefined){toast('NO ACTIVE SIGNAL TO ANALYZE');return;}const p=xy(target);let text;if(state.hintLevel===1)text=`HINT 1/3 · SIGNAL IS IN QUADRANT ${quadrant(target)} · x ${p.x<0?'−':'+'}, y ${p.y<0?'−':'+'}`;else if(state.hintLevel===2)text=`HINT 2/3 · REFERENCE ANGLE ${angleText(referenceAngle(target))} · COS IS X, SIN IS Y`;else text=`HINT 3/3 · TARGET BEARING ${angleText(target)} · ${fmt(p.x)}, ${fmt(p.y)}`;feed(text);toast(text);}
