    if(stage.kind==='boss'){if(state.spawn<=0&&state.enemies.length<2){state.spawn=(2.8-state.bossPhase*.55)+Math.random()*.8;const w=state.weapons[(Math.random()*state.weapons.length)|0],d=SIN_VALUES.find(v=>v.key===w.key)||SIN_VALUES[0],a=pick(d.angles,(Math.random()*d.angles.length)|0),coordinate=Math.random()<.5?'x':'y',valueKey=coordinateKey(a,coordinate),valueDef=SIN_VALUES.find(v=>v.key===valueKey)||SIN_VALUES[0],prompt=Math.random()<.5?'angle':'value';state.enemies.push({id:Math.random().toString(36).slice(2),angle:a,r:screenSpawnRadius(a,50),speed:Math.min(ENEMY_SPEED_CEILING,(72+state.bossPhase*8)*.75),fireCooldown:1.4+Math.random(),canShoot:true,kind:'orb',size:12,spin:0,age:0,passed:false,baseAngle:a,value:valueDef.value,valueKey,xKey:coordinateKey(a,'x'),yKey:coordinateKey(a,'y'),coordinate,solutionType:prompt==='angle'?'value':'angle',prompt,mathName:coordinate==='x'?'cos':'sin',hp:2+state.bossPhase,maxHp:2+state.bossPhase,open:true,damage:2});}}
