    function promptText(e){const coordinate=e.coordinate||'y';if(e.kind==='angle-seeker')return `x = ${e.xKey} · y = ${e.yKey}  →  θ = ?`;if(e.kind==='x-seeker')return `θ = ${angleText(e.angle)}  →  x = ?`;if(e.kind==='y-seeker')return `θ = ${angleText(e.angle)}  →  y = ?`;if(state.difficulty==='cadet'){const x=e.xKey||coordinateKey(e.angle,'x'),y=e.yKey||coordinateKey(e.angle,'y');return `θ = ${angleText(e.angle)} · x = ${x} · y = ${y}`;}if(state.difficulty==='ace')return e.prompt==='angle'?`ANGLE SIGNAL · FIND ${coordinate}`:`VALUE SIGNAL · FIND θ`;if(e.prompt==='angle')return `θ = ${angleText(e.angle)}  →  ${coordinate} = ?`;return `${coordinate} = ${e.valueKey}  →  θ = ?`;}
